import { OAuthClient, type Session, type InternalStateData } from "@atproto/oauth-client";
import { JoseKey } from "@atproto/jwk-jose";
import type { Jwk } from "@atproto/jwk";
import { AtprotoDohHandleResolver } from "@atproto-labs/handle-resolver";
import type { PortalStore } from "./store";

/**
 * ATProto OAuth for the portal.
 *
 * Deliberately built on `@atproto/oauth-client` rather than
 * `@atproto/oauth-client-node`: the Node variant pulls `@atproto-labs/fetch-node`,
 * which loads undici v8 and crashes on Bun (`webidl.util.markAsUncloneable is
 * not a function`). The runtime-agnostic package needs only WebCrypto and a
 * handle resolver, both of which Bun provides natively. Handles resolve over
 * DNS-over-HTTPS so we depend on no single AppView.
 */

export interface PortalOAuthConfig {
  /** Public origin of the portal, e.g. https://id.notorganic.info */
  publicUrl: string;
  /** ES256 private JWK used for private_key_jwt client authentication. */
  privateJwk: Jwk;
  store: PortalStore;
  dohEndpoint?: string;
  /** Development only: permits http:// authorization servers. */
  allowHttp?: boolean;
}

function clientMetadata(publicUrl: string) {
  const origin = publicUrl.replace(/\/$/, "");
  return {
    client_id: `${origin}/client-metadata.json`,
    client_name: "Not Organic",
    client_uri: origin,
    redirect_uris: [`${origin}/api/auth/callback`] as [string],
    grant_types: ["authorization_code", "refresh_token"] as ["authorization_code", "refresh_token"],
    response_types: ["code"] as ["code"],
    scope: "atproto",
    application_type: "web" as const,
    token_endpoint_auth_method: "private_key_jwt" as const,
    token_endpoint_auth_signing_alg: "ES256",
    dpop_bound_access_tokens: true as const,
    jwks_uri: `${origin}/.well-known/jwks.json`,
  };
}

/** The client metadata document served at `client_id`. */
export function clientMetadataDocument(publicUrl: string) {
  return clientMetadata(publicUrl);
}

/** The JWKS document. Public halves only — never the private key. */
export async function jwksDocument(privateJwk: Jwk) {
  const key = await JoseKey.fromJWK(privateJwk);
  return { keys: [key.publicJwk] };
}

// `Key` instances cannot round-trip through JSON, so the DPoP key is stored as
// a JWK and rebuilt on read. Everything else in these records is plain data.
async function encodeState(state: InternalStateData): Promise<string> {
  const { dpopKey, ...rest } = state;
  return JSON.stringify({ ...rest, dpopKeyJwk: dpopKey.privateJwk });
}

async function decodeState(json: string): Promise<InternalStateData> {
  const { dpopKeyJwk, ...rest } = JSON.parse(json) as Record<string, unknown> & { dpopKeyJwk: Jwk };
  return { ...(rest as Omit<InternalStateData, "dpopKey">), dpopKey: await JoseKey.fromJWK(dpopKeyJwk) };
}

async function encodeSession(session: Session): Promise<string> {
  const { dpopKey, ...rest } = session;
  return JSON.stringify({ ...rest, dpopKeyJwk: dpopKey.privateJwk });
}

async function decodeSession(json: string): Promise<Session> {
  const { dpopKeyJwk, ...rest } = JSON.parse(json) as Record<string, unknown> & { dpopKeyJwk: Jwk };
  return { ...(rest as Omit<Session, "dpopKey">), dpopKey: await JoseKey.fromJWK(dpopKeyJwk) };
}

export async function createOAuthClient(config: PortalOAuthConfig): Promise<OAuthClient> {
  const key = await JoseKey.fromJWK(config.privateJwk);
  const { store } = config;

  return new OAuthClient({
    responseMode: "query",
    clientMetadata: clientMetadata(config.publicUrl),
    keyset: [key],
    allowHttp: config.allowHttp ?? false,
    handleResolver: new AtprotoDohHandleResolver({
      dohEndpoint: config.dohEndpoint ?? "https://cloudflare-dns.com/dns-query",
    }),
    runtimeImplementation: {
      createKey: (algs) => JoseKey.generate(algs),
      getRandomValues: (length) => crypto.getRandomValues(new Uint8Array(length)),
      digest: async (data, { name }) =>
        new Uint8Array(
          await crypto.subtle.digest(
            name === "sha256" ? "SHA-256" : name === "sha384" ? "SHA-384" : "SHA-512",
            data,
          ),
        ),
    },
    stateStore: {
      async get(key) {
        const json = await store.getOauthState(key);
        return json ? await decodeState(json) : undefined;
      },
      async set(key, value) {
        await store.setOauthState(key, await encodeState(value));
      },
      async del(key) {
        await store.deleteOauthState(key);
      },
    },
    sessionStore: {
      async get(did) {
        const json = await store.getOauthSession(did);
        return json ? await decodeSession(json) : undefined;
      },
      async set(did, value) {
        await store.setOauthSession(did, await encodeSession(value));
      },
      async del(did) {
        await store.deleteOauthSession(did);
      },
    },
  });
}
import { CapabilitySchema, type Capability } from "@notorganic/contracts";

/**
 * Self-hosted clients are deliberately dynamic public OAuth clients. There is
 * no shared secret or product signing key to steal: a client may only use its
 * own HTTPS origin and exact callback URL, and a user sees that origin before
 * approving narrowly-scoped access. Loopback is permitted for local desktop
 * development, but arbitrary custom schemes are not.
 */
export interface PublicAuthorizationRequest {
  clientId: string;
  redirectUri: string;
  codeChallenge: string;
  scope: string;
  state?: string;
  environment: "browser" | "mobile";
}

export const KEATING_MOBILE_CLIENT_ID = "https://keating.help/mobile";
export const KEATING_MOBILE_REDIRECT_URI = "keating:///notorganic/callback";

export const PUBLIC_CLIENT_CAPABILITIES = [
  "wallet:read",
  "usage:read",
  "billing:checkout",
  "infer:fast",
  "infer:balanced",
  "infer:reasoning",
  "infer:vision",
  "infer:embedding",
  "infer:image",
  "infer:audio",
  "judgement:evaluate",
  "realtime:connect",
] as const satisfies readonly Capability[];

export const KEATING_MOBILE_CAPABILITIES = [
  "wallet:read",
  "usage:read",
  "billing:checkout",
  "infer:balanced",
  "judgement:evaluate",
  "sync:key:read",
  "evolution:read",
  "evolution:write",
  "evolution:execute",
  "realtime:connect",
] as const satisfies readonly Capability[];

const CHALLENGE = /^[A-Za-z0-9_-]{43,128}$/;
const STATE = /^[A-Za-z0-9._~-]{0,1024}$/;

export function validatePublicAuthorization(input: Record<string, string | undefined>):
  | { ok: true; value: PublicAuthorizationRequest; scopes: readonly Capability[]; clientOrigin: string }
  | { ok: false; message: string } {
  if (input.response_type !== "code") return { ok: false, message: "Only response_type=code is supported." };
  if (input.code_challenge_method !== "S256") return { ok: false, message: "PKCE S256 is required." };
  if (!input.client_id || !input.redirect_uri || !input.code_challenge) return { ok: false, message: "client_id, redirect_uri, and code_challenge are required." };
  if (!CHALLENGE.test(input.code_challenge)) return { ok: false, message: "The PKCE code challenge is invalid." };
  if (input.state !== undefined && !STATE.test(input.state)) return { ok: false, message: "The state value is invalid." };
  let client: URL;
  let redirect: URL;
  try { client = new URL(input.client_id); redirect = new URL(input.redirect_uri); } catch { return { ok: false, message: "client_id and redirect_uri must be absolute URLs." }; }
  const isKeatingMobile = client.toString() === KEATING_MOBILE_CLIENT_ID && redirect.toString() === KEATING_MOBILE_REDIRECT_URI;
  const loopback = (url: URL) => url.protocol === "http:" && (url.hostname === "localhost" || url.hostname === "127.0.0.1" || url.hostname === "[::1]");
  if (!isKeatingMobile && (!(client.protocol === "https:" || loopback(client)) || client.pathname !== "/" || client.search || client.hash || client.username || client.password)) return { ok: false, message: "client_id must be an HTTPS origin (or loopback development origin)." };
  if (!isKeatingMobile && (!(redirect.protocol === "https:" || loopback(redirect)) || redirect.origin !== client.origin || redirect.hash || redirect.username || redirect.password)) return { ok: false, message: "redirect_uri must be an HTTPS callback on the same client origin." };
  const requested = [...new Set((input.scope ?? "").split(/\s+/).filter(Boolean))];
  if (requested.length === 0) return { ok: false, message: "Request at least one approved scope." };
  const allowed = new Set<string>(isKeatingMobile ? KEATING_MOBILE_CAPABILITIES : PUBLIC_CLIENT_CAPABILITIES);
  const parsed: Capability[] = [];
  for (const scope of requested) {
    const capability = CapabilitySchema.safeParse(scope);
    if (!capability.success || !allowed.has(scope)) return { ok: false, message: "The requested scope is not available to public clients." };
    parsed.push(capability.data);
  }
  return { ok: true, value: { clientId: isKeatingMobile ? KEATING_MOBILE_CLIENT_ID : client.origin, redirectUri: redirect.toString(), codeChallenge: input.code_challenge, scope: parsed.sort().join(" "), state: input.state, environment: isKeatingMobile ? "mobile" : "browser" }, scopes: parsed.sort(), clientOrigin: isKeatingMobile ? "Keating mobile app" : client.origin };
}

