11: export interface NotOrganicSignInAttempt {
12:   state: string;
13:   verifier: string;
14:   expiresAt: number;
15:   origin: string;
16:   /** Where to land after the session is issued. Same-origin path only. */
17:   returnTo: string;
18: }
