20: const encode = (bytes: Uint8Array) =>
21:   btoa(String.fromCharCode(...bytes))
22:     .replace(/\+/g, "-")
23:     .replace(/\//g, "_")
24:     .replace(/=+$/, "");
25: 
26: function safeReturnTo(value: string | undefined): string {
27:   return value && value.startsWith("/") && !value.startsWith("//")
28:     ? value
29:     : "/";
30: }
31: 
32: export async function beginNotOrganicSignIn(
33:   origin: string,
34:   returnTo?: string,
35: ): Promise<{ attempt: NotOrganicSignInAttempt; url: string }> {
36:   const verifier = encode(crypto.getRandomValues(new Uint8Array(32)));
37:   const state = encode(crypto.getRandomValues(new Uint8Array(32)));
38:   const challenge = encode(
39:     new Uint8Array(
40:       await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)),
41:     ),
42:   );
43:   const url = new URL("https://id.notorganic.info/authorize");
44:   url.search = new URLSearchParams({
45:     response_type: "code",
46:     client_id: origin,
47:     redirect_uri: `${origin}${NOTORGANIC_CALLBACK_PATH}`,
48:     code_challenge_method: "S256",
49:     code_challenge: challenge,
50:     state,
51:     scope: "wallet:read",
52:     product: "twyne",
53:   }).toString();
54:   return {
55:     attempt: {
56:       state,
57:       verifier,
58:       expiresAt: Date.now() + 600_000,
59:       origin,
60:       returnTo: safeReturnTo(returnTo),
61:     },
62:     url: url.href,
63:   };
64: }
65: 
66: export function readNotOrganicCallback(
67:   attempt: NotOrganicSignInAttempt,
68:   url: URL,
69: ): { code: string; verifier: string } {
70:   if (
71:     !Number.isFinite(attempt.expiresAt) ||
72:     Date.now() >= attempt.expiresAt ||
73:     url.origin !== attempt.origin ||
74:     url.pathname !== NOTORGANIC_CALLBACK_PATH ||
75:     url.hash ||
76:     url.searchParams.has("error") ||
77:     url.searchParams.getAll("state").length !== 1 ||
78:     url.searchParams.get("state") !== attempt.state ||
79:     url.searchParams.getAll("code").length !== 1 ||
80:     !url.searchParams.get("code")
81:   ) {
82:     throw new Error(
83:       "This sign-in attempt expired or belongs to another tab. Please sign in again.",
84:     );
85:   }
86:   return { code: url.searchParams.get("code")!, verifier: attempt.verifier };
87: }
88: 
89: /** Redirect to Not Organic. Resolves only if the redirect could not start. */
90: export async function startNotOrganicSignIn(returnTo?: string): Promise<void> {
91:   const { attempt, url } = await beginNotOrganicSignIn(
92:     location.origin,
93:     returnTo ?? location.pathname + location.search,
94:   );
95:   sessionStorage.setItem(NOTORGANIC_SIGN_IN_ATTEMPT, JSON.stringify(attempt));
96:   location.assign(url);
97: }
98: 
99: /** Finish the redirect on the callback page; returns where to go next. */
100: export async function completeNotOrganicSignIn(url: URL): Promise<string> {
101:   const saved = sessionStorage.getItem(NOTORGANIC_SIGN_IN_ATTEMPT);
102:   sessionStorage.removeItem(NOTORGANIC_SIGN_IN_ATTEMPT);
103:   if (!saved) throw new Error("Start signing in again from Twyne.");
104:   const attempt = JSON.parse(saved) as NotOrganicSignInAttempt;
105:   const args = readNotOrganicCallback(attempt, url);
106:   const { authClient } = await import("./auth-client");
107:   const result = await authClient.$fetch("/sign-in/notorganic", {
108:     method: "POST",
109:     body: { ...args, origin: attempt.origin },
110:   });
111:   if ((result as { error?: unknown })?.error) {
112:     throw new Error("Not Organic could not verify this sign-in.");
113:   }
114:   // The crossDomain client stores the new session cookie; refresh the atom.
115:   await authClient.getSession({ query: { disableCookieCache: true } });
116:   return safeReturnTo(attempt.returnTo);
117: }

