11: import { APIError, createAuthEndpoint } from "better-auth/api";
12: import { setSessionCookie } from "better-auth/cookies";
13: import { z } from "zod";
14: 
15: export const NOTORGANIC_PROVIDER_ID = "notorganic";
16: export const NOTORGANIC_SIGN_IN_PATH = "/auth/notorganic/";
17: 
18: export interface VerifiedNotOrganicAccount {
19:   did: string;
20:   sessionVersion: number;
21:   handle?: string;
22: }
