24: /**
25:  * Better Auth requires a unique email. Not Organic accounts don't hand one
26:  * over, so the user row carries an undeliverable, DID-derived placeholder.
27:  */
28: export async function placeholderEmailForDid(did: string): Promise<string> {
29:   const digest = await crypto.subtle.digest(
30:     "SHA-256",
31:     new TextEncoder().encode(did),
32:   );
33:   const hex = Array.from(new Uint8Array(digest).slice(0, 16), (byte) =>
34:     byte.toString(16).padStart(2, "0"),
35:   ).join("");
36:   return `${hex}@notorganic.invalid`;
37: }
