39: export function notOrganicSignIn(options: {
40:   redeem: (input: {
41:     code: string;
42:     verifier: string;
43:     /** The browser origin that started PKCE; it is the gateway client_id. */
44:     origin: string;
45:   }) => Promise<VerifiedNotOrganicAccount>;
46:   /** Persist the DID ↔ user link used for wallet, inference and entitlement. */
47:   onSignedIn: (
48:     input: VerifiedNotOrganicAccount & { userId: string },
49:   ) => Promise<void>;
50: }) {
51:   return {
52:     id: "notorganic-sign-in",
53:     endpoints: {
54:       signInNotOrganic: createAuthEndpoint(
55:         "/sign-in/notorganic",
56:         {
57:           method: "POST",
58:           body: z.object({
59:             code: z.string().min(1).max(2048),
60:             verifier: z.string().regex(/^[A-Za-z0-9._~-]{43,128}$/),
61:             origin: z.string().url().max(256),
62:           }),
63:         },
64:         async (ctx) => {
65:           let verified: VerifiedNotOrganicAccount;
66:           try {
67:             verified = await options.redeem({
68:               ...ctx.body,
69:               origin: new URL(ctx.body.origin).origin,
70:             });
71:           } catch (error) {
72:             throw new APIError("UNAUTHORIZED", {
73:               message:
74:                 error instanceof Error
75:                   ? error.message
76:                   : "Not Organic could not verify this sign-in.",
77:             });
78:           }
79:           const adapter = ctx.context.internalAdapter;
80:           const name = verified.handle ?? verified.did;
81:           const account = await adapter.findAccountByProviderId(
82:             verified.did,
83:             NOTORGANIC_PROVIDER_ID,
84:           );
85:           let user = account ? await adapter.findUserById(account.userId) : null;
86:           if (!user) {
87:             user = await adapter.createUser({
88:               email: await placeholderEmailForDid(verified.did),
89:               name,
90:               emailVerified: false,
91:             });
92:             if (account) {
93:               await adapter.updateAccount(account.id, { userId: user.id });
94:             } else {
95:               await adapter.linkAccount({
96:                 accountId: verified.did,
97:                 providerId: NOTORGANIC_PROVIDER_ID,
98:                 userId: user.id,
99:               });
100:             }
101:           } else if (verified.handle && user.name !== verified.handle) {
102:             user = await adapter.updateUser(user.id, { name: verified.handle });
103:           }
104:           await options.onSignedIn({ ...verified, userId: user.id });
105:           const session = await adapter.createSession(user.id);
106:           await setSessionCookie(ctx, { session, user });
107:           return ctx.json({
108:             user: { id: user.id, name: user.name, did: verified.did },
109:           });
110:         },
111:       ),
112:     },
113:   } satisfies BetterAuthPlugin;
