function publicClientProducts(): Record<string, Product> {
  const configured =
    optionalJson<Record<string, string>>("PUBLIC_CLIENT_PRODUCT_CATALOG") ?? {};
  const catalog: Record<string, string> = {
    "https://stich.cc": "stich",
    ...configured,
  };
  return Object.fromEntries(
    Object.entries(catalog).map(([clientId, product]) => {
      let client: URL;
      try {
        client = new URL(clientId);
      } catch (error) {
        throw new Error(
          `PUBLIC_CLIENT_PRODUCT_CATALOG contains an invalid client id: ${clientId}`,
          { cause: error },
        );
      }
      if (client.protocol !== "https:" || client.origin !== clientId) {
        throw new Error(
          `PUBLIC_CLIENT_PRODUCT_CATALOG keys must be exact HTTPS origins: ${clientId}`,
        );
      }
      return [clientId, parseProductId(product)];
    }),
  );
}

