import { describe, expect, test } from "bun:test";
import { decodeJwt, exportJWK, generateKeyPair, SignJWT } from "jose";
import {
  ASSERTION_TOKEN_TYPE,
} from "@notorganic/contracts";
import { TokenService } from "./auth";
import type { GatewayConfig, ProviderStore, PublicDeviceSessionRecord } from "./types";

const secret = new TextEncoder().encode("a".repeat(32));
const gatewayKeys = await generateKeyPair("EdDSA", { extractable: true });
const productKeys = await generateKeyPair("EdDSA", { extractable: true });
const gatewayPrivateJwk = await exportJWK(gatewayKeys.privateKey);
const gatewayPublicJwk = await exportJWK(gatewayKeys.publicKey);
const productPublicJwk = await exportJWK(productKeys.publicKey);

const unusedStore = {
  reserve: async () => ({ requestId: "unused", status: "reserved" as const }),
  consumeDpopProof: async () => true,
} as unknown as ProviderStore;

function config(
  now = Date.now(),
  store: ProviderStore = unusedStore,
): GatewayConfig {
  return {
    store,
    gatewayIssuer: "https://gateway.test",
    gatewayAudience: "notorganic",
    gatewaySigningPrivateJwk: gatewayPrivateJwk,
    gatewaySigningPublicJwk: gatewayPublicJwk,
    productAssertionKeys: { twyne: productPublicJwk },
    portkeyApiKey: "private",
    pseudonymSecret: secret,
    now: () => now,
  };
}

describe("TokenService", () => {
  test("exchanges a 60 second assertion for a five minute DPoP token", async () => {
    const now = Math.floor(Date.now() / 1000);
    const { publicKey } = await generateKeyPair("ES256");
    const publicJwk = await exportJWK(publicKey);
    const jkt = await (
      await import("jose")
    ).calculateJwkThumbprint(publicJwk);
    const assertion = await new SignJWT({
      typ: ASSERTION_TOKEN_TYPE,
      session_version: 1,
      capabilities: ["infer:fast", "responses:read"],
      environment: "browser",
      client_jkt: jkt,
    })
      .setProtectedHeader({ alg: "EdDSA" })
      .setIssuer("twyne")
      .setSubject("did:plc:alice")
      .setAudience("notorganic")
      .setIssuedAt(now)
      .setExpirationTime(now + 60)
      .setJti("assertion-123")
      .sign(productKeys.privateKey);

    const token = await new TokenService(config(now * 1000)).exchange({
      assertion,
      dpopJwk: publicJwk,
      requestedScope: "infer:fast",
    });

    expect(token.token_type).toBe("DPoP");
    expect(token.expires_in).toBe(300);
    expect(token.scope).toBe("infer:fast");
  });

  test("rejects capability escalation", async () => {
    const now = Math.floor(Date.now() / 1000);
    const { publicKey } = await generateKeyPair("ES256");

