import { OAuthClient } from "@atproto/oauth-client";
import { exportJWK, generateKeyPair } from "jose";
import type { Jwk } from "@atproto/jwk";
import type { PortalStore } from "./store";
import { createOAuthClient } from "./oauth";

const { privateKey } = await generateKeyPair("ES256", { extractable: true });
const privateJwk = await exportJWK(privateKey) as Jwk;
const upstream = spyOn(OAuthClient.prototype, "authorize");
afterEach(() => upstream.mockReset());

async function authorize(destination: string, allowHttp = false) {
  upstream.mockResolvedValue(new URL(destination));
  const client = await createOAuthClient({
    publicUrl: "https://id.example.test", privateJwk, store: {} as PortalStore, allowHttp,
  });
  return client.authorize("synthetic.test", { scope: "atproto" });
}

