/** Public clients prove PKCE possession; the provider, not the client, binds
 * the resulting token to the DID that approved the portal authorization. */
async exchangePublicCode(input: { codeHash: string; codeVerifier: string; clientId: string; redirectUri: string; dpopJwk?: JWK; createDeviceSession?: boolean; deviceName?: string }): Promise<PublicCapabilityResponse> {
  if (!input.dpopJwk) throw new GatewayError(400, "invalid_request_error", "A DPoP public key is required.", "missing_dpop_key", "dpop_jwk");
  if (!isPublicDpopJwk(input.dpopJwk)) throw new GatewayError(400, "invalid_request_error", "dpop_jwk must be an asymmetric public JWK.", "invalid_dpop_key", "dpop_jwk");
  const product = approvedPublicClientProduct(input.clientId, this.config.publicClientProducts);
  const verifierHash = await sha256Base64url(input.codeVerifier);
  const jkt = await calculateJwkThumbprint(input.dpopJwk);
  const nowMs = this.config.now?.() ?? Date.now();
  const credential = input.createDeviceSession ? newDeviceCredential() : undefined;
  const tokenHash = credential ? await sha256Base64url(credential.token) : undefined;
  const expiresAt = credential ? nowMs + DEVICE_SESSION_TTL_MS : undefined;
  const code = await this.config.store.consumePublicAuthorizationCode?.({
    codeHash: input.codeHash,
    codeVerifierHash: verifierHash,
    clientId: input.clientId,
    redirectUri: input.redirectUri,
